export const fallbackTrivia=[{"id":"daily-sci-01","category":"과학","question":"밤하늘의 달이 밝게 보이는 주된 이유는?","options":["달이 햇빛을 반사해서","달 표면에 불이 타서","지구의 가로등을 모아서","달 속의 전구가 켜져서"],"answer":0,"explanation":"달은 태양처럼 스스로 빛을 내는 별이 아니에요. 태양빛이 달 표면에 반사되어 우리 눈에 들어옵니다.","source":{"title":"NASA · Top Moon Questions","url":"https://science.nasa.gov/moon/top-moon-questions/"},"verifiedAt":"2026-11-17"},{"id":"daily-hist-01","category":"역사","question":"훈민정음을 창제한 조선의 왕은?","options":["정조","세종","태조","영조"],"answer":1,"explanation":"세종은 백성이 쉽게 읽고 쓸 수 있도록 훈민정음을 창제했어요. 1443년에 창제하고 1446년에 반포했습니다.","source":{"title":"국가유산청 국가유산포털 · 훈민정음(해례본)","url":"https://www.heritage.go.kr/heri/html/HtmlPage.do?pageNo=5_4_2&pg=%2Funesco%2FMemHeritage%2FMemHeritage_01.jsp"},"verifiedAt":"2026-11-17"},{"id":"daily-geo-01","category":"지리","question":"지구에서 면적이 가장 넓은 대양은?","options":["북극해","인도양","태평양","대서양"],"answer":2,"explanation":"태평양은 지구에서 면적이 가장 넓은 대양이에요. 지구의 대양 중 평균 수심도 가장 깊습니다.","source":{"title":"NOAA Ocean Exploration · How Big Is the Pacific Ocean?","url":"https://oceanexplorer.noaa.gov/ocean-fact/pacific-size/"},"verifiedAt":"2026-11-17"},{"id":"daily-animal-01","category":"동물","question":"문어의 심장은 몇 개일까요?","options":["1개","2개","4개","3개"],"answer":3,"explanation":"문어는 심장이 세 개예요. 두 개는 아가미로 혈액을 보내고, 나머지 하나는 몸의 다른 부분으로 혈액을 보냅니다.","source":{"title":"Monterey Bay Aquarium · Red Octopus","url":"https://www.montereybayaquarium.org/animals-the-ocean/animals-a-to-z/red-octopus"},"verifiedAt":"2026-11-17"},{"id":"daily-nature-01","category":"자연","question":"별 모양 눈 결정의 기본 대칭은 보통 몇 갈래일까요?","options":["여섯 갈래","다섯 갈래","일곱 갈래","아홉 갈래"],"answer":0,"explanation":"얼음의 분자 배열 때문에 별 모양 눈 결정에는 여섯 갈래의 기본 구조가 나타나요. 모든 눈 결정이 똑같은 별 모양인 것은 아니며 기둥이나 바늘 모양도 있습니다.","source":{"title":"NOAA · How Do Snowflakes Form?","url":"https://www.noaa.gov/stories/how-do-snowflakes-form-science-behind-snow"},"verifiedAt":"2026-11-17"},{"id":"daily-art-01","category":"예술","question":"「별이 빛나는 밤」을 그린 화가는?","options":["클로드 모네","빈센트 반 고흐","파블로 피카소","살바도르 달리"],"answer":1,"explanation":"「별이 빛나는 밤」은 빈센트 반 고흐의 작품이에요. 뉴욕 현대미술관 MoMA의 작품 기록에서 작가를 확인할 수 있습니다.","source":{"title":"MoMA · Vincent van Gogh, The Starry Night","url":"https://www.moma.org/collection/works/79802?locale=en"},"verifiedAt":"2026-11-17"},{"id":"daily-general-01","category":"일반","question":"전통적인 점자의 기본 한 칸에는 점 자리가 몇 개일까요?","options":["4개","5개","6개","9개"],"answer":2,"explanation":"기본 6점 점자 한 칸은 가로 2칸, 세로 3칸의 여섯 자리로 이루어져요. 점의 조합으로 글자나 기호를 나타냅니다.","source":{"title":"American Foundation for the Blind · What Is Braille?","url":"https://www.afb.org/blindness-and-low-vision/braille/what-braille"},"verifiedAt":"2026-11-17"}];
